/**
 * Cross-SDK entrypoint ID derivation tests.
 *
 * Reads vectors generated by the Rust SDK's `groundhog-test-vectors entrypoint-id`
 * and verifies the TypeScript implementation produces identical results.
 */
import { describe, it, expect } from "vitest";
import { deriveEntrypointID, toHex } from "../../src/utils/index.js";
import { existsSync, readFileSync } from "fs";

const VECTORS_PATH = "test/fixtures/entrypoint_vectors.json";

interface EntrypointVector {
  interface: string | null;
  version_str: string;
  derived_major_version: string;
  method: string;
  expected_id: string;
}

interface VectorFile {
  version: number;
  category: string;
  vectors: EntrypointVector[];
}

describe("cross-SDK: entrypoint ID derivation", () => {
  if (!existsSync(VECTORS_PATH)) {
    it.skip(`no vectors file at ${VECTORS_PATH} (run groundhog-test-vectors entrypoint-id to generate)`, () => {});
    return;
  }

  let data: VectorFile;
  try {
    data = JSON.parse(readFileSync(VECTORS_PATH, "utf-8"));
  } catch {
    it.skip(`vectors file at ${VECTORS_PATH} is not valid JSON (regenerate with groundhog-test-vectors)`, () => {});
    return;
  }

  if (!data.vectors || data.vectors.length === 0) {
    it.skip("vectors file is empty", () => {});
    return;
  }

  for (const vec of data.vectors) {
    const label = `${vec.interface ?? "null"}/${vec.version_str}/${vec.method}`;

    it(`matches Rust SDK: ${label}`, async () => {
      const id = await deriveEntrypointID(vec.interface, vec.version_str, vec.method);
      // The Rust side outputs uppercase hex as a 16-char string (u64 big-endian)
      const tsHex = toHex(id).toUpperCase().padStart(16, "0");
      expect(tsHex).toBe(vec.expected_id);
    });
  }
});
